echo "== endpoints checked + demand since $SINCE (UTC): true (no placeholder hosts) and raw"
"${W[@]}" --command "SELECT COUNT(DISTINCT CASE WHEN NOT $PH_SQL THEN url END) AS endpoints, COUNT(DISTINCT url) AS endpoints_raw, SUM(CASE WHEN NOT $PH_SQL THEN 1 ELSE 0 END) AS checks, COUNT(*) AS checks_raw, SUM(CASE WHEN check_type != 'self-checked' AND NOT $PH_SQL THEN 1 ELSE 0 END) AS demand, SUM(CASE WHEN check_type != 'self-checked' THEN 1 ELSE 0 END) AS demand_raw, SUM(CASE WHEN $PH_SQL THEN 1 ELSE 0 END) AS placeholder_checks FROM spot_receipts WHERE created_at >= '${SINCE}T00:00:00Z'"
